from pathlib import Path
import json,hashlib,re,platform
p=Path(__file__).resolve().parent
read=lambda name:json.loads((p/name).read_text())
log=(p/'tests.log').read_text();tests=int(re.search(r'^# tests (\d+)$',log,re.M)[1]);assert tests==int(re.search(r'^# pass (\d+)$',log,re.M)[1]);assert re.search(r'^# fail 0$',log,re.M)
current={str(f.relative_to(p/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted((p/'runtime').rglob('*')) if f.is_file()};assert current==read('bench-runtime-sha256.json')
jsc=read('mixed-jsc-results.json');assert jsc['candidateVersion']=='3.1.2' and jsc['baselineVersion']=='3.1.1' and len(jsc['runs'])==360
ranges=[]
for mode in ['cold','sequence']:
 for mixed in [False,True]:
  rows=[r for r in jsc['comparisons'] if r['mode']==mode and r['intentionalBehaviorChange']==mixed]
  pct=[100*(r['candidate']['sampledPeakFootprint']/r['baseline']['sampledPeakFootprint']-1) for r in rows];ms=[r['candidate']['milliseconds']-r['baseline']['milliseconds'] for r in rows]
  ranges.append({'mode':mode,'mixed':mixed,'scenarios':len(rows),'peakFootprintPercent':[round(min(pct),3),round(max(pct),3)],'deltaMilliseconds':[round(min(ms),3),round(max(ms),3)]})
native=[]
for name in ['native-first-load-results.json','native-filled-first-load-results.json']:
 j=read(name);assert len(j['runs'])==240
 pct=[100*(r['candidate']['sampledMaxHeapBytes']/r['baseline']['sampledMaxHeapBytes']-1) for r in j['comparisons']];ms=[r['candidate']['medianMs']-r['baseline']['medianMs'] for r in j['comparisons']]
 native.append({'report':name,'freshProcesses':240,'peakHeapPercent':[round(min(pct),3),round(max(pct),3)],'deltaMilliseconds':[round(min(ms),3),round(max(ms),3)]})
churn=read('mixed-native-churn-results.json')['results'];assert len(churn)==20
for r in churn:assert r['lyricResponses']==r['completedResponses']==240 and r['httpCalls']==120 and r['warmHTTP']==r['activeHTTP']==0 and r['maxActiveHTTP']==1 and r['maxCacheCharacters']<=(32000 if r['mode']=='compact' else 64000)
pressure=read('native-pressure-results.json');assert len(pressure['runs'])==16
for r in pressure['runs']:assert r['peakHTTP']==1 and r['admissionTimers']==0 and r['retryTranslated']==1 and r['peakLiveInvocations']<=2
live=read('mixed-live-results.json');assert len(live['results'])==2
for r in live['results']:assert r['changed']==5 and r['warmHTTP']==0 and len(r['calls'])==1
summary={'version':'3.1.2','adapter':14,'baseline':'3.1.1','tests':{'passed':tests,'failed':0,'addedSince311':tests-1357,'egernYAML':'passed'},'nativePolicies':'Five compiled native adapters; JSON/protobuf; zh-CN/zh-TW; pure Chinese, Latin spans, old identity/conversion/legacy/source caches, checked no-op proofs, cache-only, native source/timing/palette preservation, static-to-timed upgrades and fallback retained.','livePublicRequests':{'actualCandidateTranslator':2,'inputRowsPerTarget':5,'wholeRowAutoObservation':2,'forcedEnExperimentNotShipped':2,'standaloneFragmentObservation':2,'warmHTTP':0},'jsc':{'freshProcesses':360,'ranges':ranges,'report':'mixed-jsc-results.json'},'nativeCold':native,'mixedChurn':{'configurations':20,'songChangesPerConfiguration':120,'lyricResponses':4800,'httpCalls':2400,'warmHTTP':0,'unfinishedHTTP':0,'maxActiveHTTP':1,'standardMaxCacheCharacters':max(r['maxCacheCharacters'] for r in churn if r['mode']=='standard'),'compactMaxCacheCharacters':max(r['maxCacheCharacters'] for r in churn if r['mode']=='compact'),'sampledHeapBytes':[min(r['sampledMaxHeapBytes'] for r in churn),max(r['sampledMaxHeapBytes'] for r in churn)],'report':'mixed-native-churn-results.json'},'pressure':{'trials':16,'maxLiveInvocations':max(r['peakLiveInvocations'] for r in pressure['runs']),'maxActiveHTTP':1,'admissionTimers':0,'settledRetryPreservesTranslation':True,'report':'native-pressure-results.json'},'runtimeSHA256':current,'scope':'Local source reproduction, 1515 automated checks, live unauthenticated synthetic translation requests and macOS JSC/Node native mocks. Not native app import, iPhone traffic, process memory ceiling, complete catalog coverage or VPN acceptance.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# VerseLyrics 3.1.2 measurements','',f'**{tests} automated tests pass, zero fail**; 158 added since 3.1.1. Egern native YAML validation passes. Baseline is the actually published 3.1.1 runtime/source commit 5f8e1b36cafe1fdf52b9a5100efea22ac4a6c52e. Adapter 14 is unchanged. Runtime SHA256 values are recorded in validation-summary.json and bench-runtime-sha256.json.','', '## Functional evidence','', 'The locally executed 3.1.1 source skips all three reproduction cases: empty cache, old mixed identity pairs and old conversion pairs. Candidate 3.1.2 translates embedded English in each using one batch, retains pure Chinese and composes Chinese/punctuation literally. See regression-reproduction.json. Two live whole-row auto calls left four embedded English phrases unchanged; two forced-English experiments translated English but reworded Chinese and are not used. Two standalone fragment observations confirmed newline alignment. Finally two live calls through the actual candidate translator produced five mixed translations for each Chinese target; warm reopen made zero calls. The synthetic inputs and exact responses are retained in mixed-*-observations.json and mixed-live-results.json. They contain no account credentials, Spotify private traffic or copied song lyrics.','', '## macOS JavaScriptCore','', '360 fresh processes: six alternating trials per version/scenario, 20 cold cases and ten 32-context sequence cases. Public JavaScriptCore C API; sequence contexts/groups are released without forcing GC. Native HTTP mocks have zero latency and drain before completion. Unchanged case byte fingerprints and HTTP counts must match. Mixed cases intentionally do more work than the broken 3.1.1 skip: one query per original row, combined into one HTTP for the 48-row fixtures, including ten spans per row. No-op output is unchanged and uses the bounded checked marker.','', '| Mode | Cases | Peak footprint change | Total elapsed delta (ms) |','| --- | --- | --- | --- |']
for r in ranges:lines.append('| '+r['mode']+(' mixed' if r['mixed'] else ' unchanged')+' | '+str(r['scenarios'])+' | '+str(r['peakFootprintPercent'])+'% | '+str(r['deltaMilliseconds'])+' |')
lines += ['', 'These ranges are scenario medians across alternating process trials. Mixed cold work restores an actual translation HTTP and output composition that 3.1.1 omitted; it therefore consumes more CPU and memory than skipping translation. Sequence elapsed deltas cover 32 fresh contexts, not one lyric response. Footprint includes harness, code compilation, JIT and allocator effects; samples are not every allocation. This is not a universal speed or memory reduction.','', '## First invocation and filled caches','', 'Ten unchanged Loon scenarios, twelve alternating fresh processes per version/scenario: 240 empty-cache processes and 240 populated-cache processes. Unrelated filled caches occupy 48,000-60,000 serialized characters. Each invocation compiles a fresh VM; 32 MiB V8 old-space is a harness setting, not a Loon memory limit. Output hashes and HTTP counts match 3.1.1.','', '| Mode | Peak sampled heap change | Elapsed median delta (ms) |','| --- | --- | --- |']
for r in native:lines.append('| '+r['report']+' | '+str(r['peakHeapPercent'])+'% | '+str(r['deltaMilliseconds'])+' |')
lines += ['', '## Continuous mixed-song changes and pressure','', 'Twenty independent 32 MiB old-space Node processes cover five clients, JSON/protobuf and standard/compact cache. Each process handles 120 distinct song IDs with 24 original timed rows, alternates 80 translated and 40 no-op songs, seeds old identity/conversion pairs and immediately reopens each song. Total 4,800 fresh native responses completed, 2,400 translation HTTP calls, zero warm calls, zero unfinished HTTP and maximum one active HTTP per process. Native timing, original words, palette and per-format output SHA256 agree across clients and cache modes. GC runs every six songs; samples include harness and VM generations.',f"Maximum serialized cache: standard {summary['mixedChurn']['standardMaxCacheCharacters']} / 64,000 characters; compact {summary['mixedChurn']['compactMaxCacheCharacters']} / 32,000. Existing entry caps remain 128/64.",'', 'Sixteen separate Loon pressure trials compare same-song and distinct-song bursts of 60 arrivals at two-millisecond spacing, with 400 ms delayed HTTP callbacks. Maximum two live invocations, one active HTTP and zero admission timers. Callbacks drain and the settled-song retry retains translation. Synchronous storage mocks cannot prove atomic native admission or memory reclamation.','', '## Reproduction and boundary','', 'Generate JSC fixtures as listed in README.md and compile jsc-memory-runner.c with the public macOS SDK and JavaScriptCore framework. Run `python3 run-final-312.py /path/to/node /path/to/311`; the driver snapshots every runtime and rejects changes between measurement steps. Source tests and Ruby YAML checks are separate commands in README.md.','', 'macOS JSC footprint and Node heap measurements do not establish Loon/iOS native network-buffer usage, an OS process ceiling, real-phone load time or VPN stability. No iPhone import or VPN acceptance was performed. All work, cache, source request, response, URL, output and deadline bounds remain; restoring mixed translation necessarily differs from the previous no-op path.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in summary.items() if k not in ['runtimeSHA256','nativePolicies']},ensure_ascii=False))
